#!/usr/bin/env bash
# Install locally or via the command generated by Xboard Server Management.
set +x
set -euo pipefail
umask 077

fail() { printf '%s\n' "$*" >&2; exit 1; }
mode=standalone
panel_url=
api_key=
machine_id=
version=dev
binary=
migrate=0
instance=
while (( $# )); do
  case "$1" in
    --migrate-xboard-node) migrate=1; shift ;;
    --mode|--panel|--token|--machine-id|--version|--binary|--instance)
      (( $# >= 2 )) || fail "缺少 $1 的参数。"
      case "$1" in
        --mode) mode=$2 ;;
        --panel) panel_url=$2 ;;
        --token) api_key=$2 ;;
        --machine-id) machine_id=$2 ;;
        --version) version=$2 ;;
        --binary) binary=$2 ;;
        --instance) instance=$2; [[ $instance =~ ^[a-z0-9][a-z0-9-]{0,31}$ ]] || fail "实例名称无效。" ;;
      esac
      shift 2 ;;
    -h|--help)
      echo 'sudo bash install.sh [--binary /path/to/proxy-node]'
      echo '迁移旧 systemd 节点：在机器安装命令末尾追加 --migrate-xboard-node'
      echo 'Xboard: --mode machine --panel HTTPS_URL --token MACHINE_TOKEN --machine-id ID [--version REF] [--instance NAME]'
      exit 0 ;;
    --*) fail "未知参数：$1" ;;
    *) [[ -z "$binary" ]] || fail '只能指定一个 proxy-node 文件。'; binary=$1; shift ;;
  esac
done

[[ $EUID == 0 && $(uname -s) == Linux ]] || fail '请在 Linux 节点上以 root 安装。'
for command in python3 systemctl install getent useradd mktemp flock; do
  command -v "$command" >/dev/null || fail "缺少命令：$command"
done
[[ $version =~ ^[a-zA-Z0-9][a-zA-Z0-9._-]*$ ]] || fail '无效的版本或 Git ref。'

install_dir=/opt/mx-websocket-node
config_dir=/etc/mx-websocket-node
config_file="$config_dir/config.json"
new=mx-websocket-node.service
state_name=mx-websocket-node
if [[ -n $instance ]]; then
  install_dir="$install_dir/$instance"
  config_file="$config_dir/$instance.json"
  state_name="mx-websocket-node-$instance"
  new="mx-websocket-node@$instance.service"
fi
unit_file="/etc/systemd/system/$new"
# Serialize installs because they share the system user and systemd reload.
exec 9>/run/lock/mx-websocket-node-install.lock
flock -w 180 9 || fail '另一项节点安装仍在运行，请等待它完成。'
if [[ -e $config_file || -L $config_file ]]; then
  fail "配置 $config_file 已存在；请使用不同的实例名称。"
fi
load_state=$(systemctl show -p LoadState --value "$new") ||
  fail "无法查询 systemd 单元 $new。"
if [[ -e $unit_file || -L $unit_file || $load_state != not-found ]]; then
  fail "systemd 单元 $new 已存在；请选择其他实例名称。"
fi
legacy=xboard-node.service
if (( migrate )); then
  [[ $mode == machine ]] || fail '旧服务迁移仅支持面板的机器安装命令。'
  systemctl is-active --quiet "$legacy" || fail '未找到正在运行的 xboard-node.service。'
fi
for service in "$legacy" proxy-node.service; do
  if [[ -n $instance ]] || { (( migrate )) && [[ $service == "$legacy" ]]; }; then continue; fi
  if systemctl is-active --quiet "$service"; then
    fail "$service 仍在运行。请先确认迁移窗口并停用旧服务，再重试。"
  fi
done

if [[ -z $binary ]]; then
  for candidate in ./proxy-node /opt/proxy-node/proxy-node /usr/local/bin/mx-proxy-node /usr/local/bin/proxy-node; do
    if [[ -f $candidate && -r $candidate ]]; then
      binary=$candidate
      break
    fi
  done
fi
[[ -n $binary && -f $binary && -r $binary ]] ||
  fail '未找到原版 MX 二进制。请把对应架构的 proxy-node 解压到当前目录，再运行面板命令。'
python3 - "$binary" <<'PY'
import platform
import sys
with open(sys.argv[1], "rb") as binary:
    header = binary.read(20)
expected = {"x86_64": 62, "aarch64": 183}.get(platform.machine())
if (expected is None or len(header) != 20 or header[:6] != b"\x7fELF\x02\x01"
        or int.from_bytes(header[18:20], "little") != expected):
    sys.exit("proxy-node 文件无效，或架构与本机不匹配。")
PY

case "$mode" in
  machine)
    [[ -n $panel_url && -n $api_key && $machine_id =~ ^[1-9][0-9]*$ ]] ||
      fail '机器模式需要 --panel、--token 和 --machine-id。'
    config_id=$machine_id ;;
  standalone)
    [[ -z $machine_id ]] || fail '使用 --machine-id 时须指定 --mode machine。'
    if [[ -z $panel_url ]]; then read -r -p 'Xboard 面板 HTTPS 地址：' panel_url </dev/tty; fi
    read -r -p '面板节点 ID：' config_id </dev/tty
    if [[ -z $api_key ]]; then
      read -r -s -p '面板服务端通信密钥（api_key）：' api_key </dev/tty
      printf '\n'
    fi ;;
  *) fail '仅支持 machine 和 standalone 模式。' ;;
esac
[[ -n ${api_key//[[:space:]]/} ]] || fail '通信密钥不能为空。'

scratch=$(mktemp -d)
cutover=0
legacy_enabled=0
cleanup() {
  local status=$?
  trap - EXIT
  set +e
  unset api_key
  if (( status != 0 && cutover )); then
    echo '迁移失败，正在恢复旧 Xboard-Node 服务。' >&2
    systemctl disable --now "$new" >/dev/null 2>&1
    rm -f -- "$unit_file" "$config_file"
    systemctl daemon-reload
    if (( legacy_enabled )); then systemctl enable "$legacy"; fi
    if systemctl start "$legacy" && systemctl is-active --quiet "$legacy"; then
      echo '旧服务已恢复。' >&2
    else
      echo '旧服务恢复失败，请检查 journalctl -u xboard-node。' >&2
    fi
  fi
  rm -rf -- "$scratch"
  exit "$status"
}
trap cleanup EXIT
source_dir=
if [[ -n ${BASH_SOURCE[0]:-} && -f ${BASH_SOURCE[0]} && $version == dev ]]; then
  source_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
fi
files=(mx_node.py machine.py config.example.json requirements.txt node_config.defaults.json mx-websocket-node.service)
if [[ "$mode" == machine ]]; then
  command -v curl >/dev/null || fail "机器模式需要 curl。"
fi
if [[ -z "$source_dir" || ! -f "$source_dir/machine.py" ]]; then
  command -v curl >/dev/null || fail '远程安装需要 curl。'
  source_dir=$scratch
  repo="https://raw.githubusercontent.com/Furina-Lee/MX-WebSocket-Node/$version"
  for file in "${files[@]}"; do
    curl -fsSL --proto '=https' --proto-redir '=https' --retry 2 -- "$repo/$file" >"$scratch/$file"
  done
fi

printf '%s' "$api_key" | python3 -c '
import json, pathlib, subprocess, sys
from urllib.parse import urlsplit
template, output, url, node_id, mode, migrate, install_dir, state_name = sys.argv[1:]
parsed = urlsplit(url)
if (parsed.scheme != "https" or not parsed.hostname or parsed.username is not None
        or parsed.password is not None or parsed.query or parsed.fragment
        or url != url.strip()):
    sys.exit("请输入不带凭据、查询参数或片段的 HTTPS 面板地址。")
if not node_id.isascii() or not node_id.isdecimal() or int(node_id) <= 0:
    sys.exit("ID 必须是正整数。")
data = json.loads(pathlib.Path(template).read_text(encoding="utf-8"))
url, key = url.rstrip("/"), sys.stdin.read()
data["panel"].update(api_host=url, api_key=key, node_config_defaults_path=install_dir + "/node_config.defaults.json")
state_dir = "/var/lib/" + state_name
data["bridge"].update(binary=install_dir + "/proxy-node", state_dir=state_dir)
data["mundoproxy"]["asset_path"] = state_dir
data["cert"].update(cert_file=state_dir + "/cert.pem", key_file=state_dir + "/key.pem")
if mode == "machine":
    payload = json.dumps({"machine_id": int(node_id), "token": key}).encode()
    result = subprocess.run(
        ["curl", "--silent", "--proto", "=https", "--connect-timeout", "8",
         "--max-time", "15", "--header", "Content-Type: application/json",
         "--header", "Accept: application/json", "--user-agent", "MX-WebSocket-Node/1.0",
         "--data-binary", "@-", "--write-out", "\n%{http_code}",
         "--", url + "/api/v2/server/machine/nodes"],
        input=payload, stdout=subprocess.PIPE, check=False,
    )
    if result.returncode:
        sys.exit(f"无法访问面板 HTTPS 接口（curl 退出码 {result.returncode}）。")
    body, _, status = result.stdout.rpartition(b"\n")
    if status != b"200":
        code = status.decode("ascii", errors="replace")
        if status in (b"401", b"403"):
            sys.exit(f"机器发现接口返回 HTTP {code}。请核对机器 ID、Token、启用状态及面板访问规则。")
        sys.exit(f"机器发现接口返回 HTTP {code}。请检查面板地址及反向代理。")
    try:
        nodes = json.loads(body)["nodes"]
        if not isinstance(nodes, list):
            raise ValueError()
    except (ValueError, KeyError, TypeError):
        sys.exit("面板响应没有有效的节点列表。请检查面板版本和 API 路由。")
    print(f"机器认证通过，当前有 {len(nodes)} 个已启用的节点。")
    if not nodes and migrate == "1":
        sys.exit("机器没有已启用节点，已取消迁移。")
    if migrate == "1":
        try:
            ids = [str(int(node["id"])) for node in nodes]
        except (TypeError, ValueError, KeyError):
            sys.exit("面板返回了无效的节点 ID，已取消迁移。")
        if any(int(node_id) <= 0 for node_id in ids):
            sys.exit("面板返回了无效的节点 ID，已取消迁移。")
        pathlib.Path(output).with_name("nodes").write_text("\n".join(ids) + "\n", encoding="utf-8")
    if not nodes:
        print("请在面板绑定并启用节点。服务启动后会自动发现它们。")
    data["machine"] = {"id": int(node_id)}
    data["panel"].pop("node_id", None)
    data["panel"].pop("node_type", None)
else:
    data["panel"]["node_id"] = int(node_id)
with pathlib.Path(output).open("x", encoding="utf-8") as config:
    json.dump(data, config, ensure_ascii=False, indent=2)
    config.write("\n")
' "$source_dir/config.example.json" "$scratch/config.json" "$panel_url" "$config_id" "$mode" "$migrate" "$install_dir" "$state_name"
unset api_key

# Debian and Ubuntu package ensurepip separately from the Python interpreter.
if ! python3 -c "import ensurepip" >/dev/null 2>&1; then
  if command -v apt-get >/dev/null && [[ /usr/bin/python3 -ef $(command -v python3) ]]; then
    echo "正在安装 Python 虚拟环境依赖（python3-venv）..."
    apt-get update
    DEBIAN_FRONTEND=noninteractive apt-get install -y python3-venv
  fi
  python3 -c "import ensurepip" >/dev/null 2>&1 ||
    fail "当前 Python 缺少 ensurepip。请安装与 python3 对应的 venv 软件包，再运行安装命令。"
fi

getent passwd mxnode >/dev/null || useradd --system --user-group --no-create-home --shell /usr/sbin/nologin mxnode
install -d -m 0755 "$install_dir"
install -d -m 0750 -o root -g mxnode "$config_dir"
install -m 0755 -- "$binary" "$install_dir/proxy-node"
for file in mx_node.py machine.py requirements.txt node_config.defaults.json; do
  install -m 0644 -- "$source_dir/$file" "$install_dir/"
done
(
  # The environment contains code and dependencies, and the service runs as mxnode.
  umask 022
  python3 -m venv "$install_dir/.venv" ||
    fail "无法创建 Python 虚拟环境。请确认此 Python 的 venv 和 ensurepip 可用后重新运行。"
  "$install_dir/.venv/bin/pip" install -r "$install_dir/requirements.txt"
)
# Repair directories left by an earlier installation using a restrictive umask.
chmod -R go+rX -- "$install_dir/.venv"
if (( migrate )); then
  command -v journalctl >/dev/null || fail '迁移验证需要 journalctl。'
  systemctl is-enabled --quiet "$legacy" && legacy_enabled=1
  cutover=1
  systemctl stop "$legacy"
fi
sed -e "s|StateDirectory=mx-websocket-node$|StateDirectory=$state_name|" \
    -e "s|/opt/mx-websocket-node|$install_dir|g" \
    -e "s|/etc/mx-websocket-node/config.json|$config_file|g" \
    "$source_dir/mx-websocket-node.service" > "$scratch/service"
install -m 0644 "$scratch/service" "$unit_file"
install -m 0640 -o root -g mxnode "$scratch/config.json" "$config_file"
systemctl daemon-reload
systemctl enable --now "$new"
if (( migrate )); then
  verified=0
  for (( attempt=0; attempt<30; attempt++ )); do
    invocation=$(systemctl show -p InvocationID --value "$new")
    startup_log=
    if [[ -n $invocation && $invocation != 00000000000000000000000000000000 ]]; then
      startup_log=$(journalctl "_SYSTEMD_INVOCATION_ID=$invocation" --no-pager -o cat)
    fi
    verified=1
    while IFS= read -r node; do
      if ! grep -Eq "[-]$node\] Started with [0-9]+ users" <<< "$startup_log"; then
        verified=0
        break
      fi
    done < "$scratch/nodes"
    if (( verified )) && systemctl is-active --quiet "$new"; then break; fi
    sleep 2
  done
  (( verified )) && systemctl is-active --quiet "$new" || fail '新服务未在 60 秒内启动全部已启用节点。'
  if (( legacy_enabled )); then systemctl disable "$legacy"; fi
  cutover=0
  echo '迁移完成。旧 Xboard-Node 的程序、systemd 单元和配置已保留，可用于回滚。'
fi
echo "节点服务已启动。可运行 journalctl -u $new -f 检查面板连接。"
